SWARM_B64

base64 -d "$TMP/package.b64" > "$TMP/package.zip"
python - "$TMP/package.zip" "$ROOT" <<'PYEXTRACT'
import sys, zipfile, pathlib, shutil
zip_path=pathlib.Path(sys.argv[1])
root=pathlib.Path(sys.argv[2])
with zipfile.ZipFile(zip_path) as z:
    for info in z.infolist():
        if info.is_dir():
            continue
        parts=pathlib.PurePosixPath(info.filename).parts
        if len(parts) < 2:
            continue
        rel=pathlib.Path(*parts[1:])
        dest=root/rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        with z.open(info) as src, open(dest, 'wb') as dst:
            shutil.copyfileobj(src, dst)
PYEXTRACT

PYTHONPATH=validation_10x10 python -m unittest discover -s validation_10x10/swarm_validation/tests -v

